mapper.select:
select s.seat_type as seatType, count(*) as seatCount from t_seat s inner join t_train_seat_occupancy o on o.train_id = s.train_id and o.seat_id = s.id and o.service_date = #{serviceDate} and o.del_flag = 0 where s.train_id = #{trainId} and (o.occupy_bitmap & #{requestMask}) = 0 and s.seat_type in
#{seatType}
group by s.seat_type having seatCount > 0

select count(*) as seatCount from t_seat s inner join t_train_seat_occupancy o on o.train_id = s.train_id and o.seat_id = s.id and o.service_date = #{serviceDate} and o.del_flag = 0 where s.train_id = #{trainId} and (o.occupy_bitmap & #{requestMask}) = 0 and s.carriage_number in
#{carriageNumber}
group by s.carriage_number

mapper.update:
update t_train_seat_occupancy
set occupy_bitmap = occupy_bitmap | #{requestMask},
    version = version + 1,
    update_time = now()
where train_id = #{trainId}
  and service_date = #{serviceDate}
  and seat_id = #{seatId}
  and version = #{version}
  and del_flag = 0
  and (occupy_bitmap & #{requestMask}) = 0

update t_train_seat_occupancy
set occupy_bitmap = occupy_bitmap & ~#{requestMask},
    version = version + 1,
    update_time = now()
where train_id = #{trainId}
  and service_date = #{serviceDate}
  and seat_id = #{seatId}
  and del_flag = 0
  and (occupy_bitmap & #{requestMask}) != 0
